components.css:
.ds-island-pill { position: relative; isolation: isolate; width: 148px; height: 36px; display: flex; align-items: center; gap: 11px; padding: 0 15px; background: var(--surface, #0c0914); border-radius: 999px; box-shadow: inset 0 1px 0 #f0dcff26, inset 0 -1px 0 #9e71ee14, 0 6px 14px #0000004d, 0 0 22px #864ddd29; cursor: default; }
.ds-island-pill::after { content: ''; pointer-events: none; position: absolute; inset: 0; border-radius: inherit; background: linear-gradient(115deg,#e9d6ff0d,transparent 35%,transparent 65%,#ad80f20a); }
.ds-cosmic-mark { position: relative; z-index: 1; flex: none; filter: drop-shadow(0 0 5px #c9a1ff55); }
.ds-island-content { position: relative; z-index: 1; display: flex; align-items: center; gap: 11px; width: 100%; height: 100%; transform-origin: center; }
.ds-cosmic-emblem, .ds-cosmic-float { display: inline-flex; flex: none; align-items: center; justify-content: center; width: 23px; height: 23px; }
.ds-cosmic-float { animation: planet-float 3.8s ease-in-out infinite; }
.ds-isle-wordmark { position: relative; z-index: 1; font-size: 13px; line-height: 1; font-weight: 600; letter-spacing: -.02em; text-shadow: 0 1px 5px #100621; }
.ds-cosmic-sky { position: absolute; inset: 0; overflow: hidden; border-radius: inherit; pointer-events: none; }
.ds-nebula { position: absolute; width: 130px; height: 52px; border-radius: 50%; will-change: transform; }
.ds-nebula-near { left: -25px; top: 12px; background: radial-gradient(ellipse,#a36aef70 0%,#7c3fbb2e 38%,transparent 70%); animation: nebula-flow 9s ease-in-out infinite alternate; }
.ds-nebula-far { right: -45px; top: -31px; background: radial-gradient(ellipse,#e6adff60 0%,#9864ff35 36%,transparent 70%); animation: nebula-flow 12s ease-in-out -5s infinite alternate-reverse; }
.ds-cosmic-stars { position: absolute; inset: 0; width: 100%; height: 100%; fill: #eddcff; color: #eddcff; opacity: .65; animation: star-breathe 5s ease-in-out infinite alternate; }
.ds-orbit-trail { position: absolute; left: 28%; top: -27px; width: 135px; height: 62px; border: 1px solid #d5b4ff1a; border-radius: 50%; transform: rotate(-16deg); }
.ds-cosmic-comet { position: absolute; left: 0; top: 10px; width: 28px; height: 1px; border-radius: 50%; background: linear-gradient(90deg,transparent,#cba4ff80,#fff0ff); box-shadow: 1px 0 4px #e6c2ff66; opacity: 0; animation: comet-pass 6.8s ease-out 1.2s infinite; }
.ds-ready-signal { position: relative; z-index: 1; margin-left: auto; width: 12px; height: 12px; display: grid; place-items: center; }
.ds-ready-dot { width: 3px; height: 3px; border-radius: 50%; background: #ead6ff; box-shadow: 0 0 6px #c699ff99; }
.ds-ready-orbit { position: absolute; inset: 0; border-radius: 50%; border: 1px solid #ceb0ff29; border-top-color: #dfc5ff99; animation: orbit-turn 10s linear infinite; }
@keyframes nebula-flow { from { transform: translate3d(-6px,0,0) rotate(-10deg) scale(.9); } to { transform: translate3d(24px,-8px,0) rotate(18deg) scale(1.15); } }
@keyframes star-breathe { from { opacity: .3; } to { opacity: .8; } }
@keyframes orbit-turn { to { transform: rotate(360deg); } }
@keyframes planet-float { 0%,100% { transform: translateY(1px) rotate(-3deg); } 50% { transform: translateY(-1.5px) rotate(3deg); } }
@keyframes comet-pass { 0% { transform: translate3d(-32px,14px,0) rotate(-12deg); opacity: 0; } 5% { opacity: .85; } 24% { transform: translate3d(164px,-12px,0) rotate(-12deg); opacity: 0; } 100% { transform: translate3d(164px,-12px,0) rotate(-12deg); opacity: 0; } }
.ds-island-canvas[data-motion-paused="true"] .ds-nebula,
.ds-island-canvas[data-motion-paused="true"] .ds-cosmic-stars,
.ds-island-canvas[data-motion-paused="true"] .ds-ready-orbit,
.ds-island-canvas[data-motion-paused="true"] .ds-cosmic-float,
.ds-island-canvas[data-motion-paused="true"] .ds-cosmic-comet { animation-play-state: paused; }
@media (prefers-reduced-motion: reduce) { .ds-nebula, .ds-cosmic-stars, .ds-ready-orbit, .ds-cosmic-float, .ds-cosmic-comet { animation: none; will-change: auto; } .ds-cosmic-comet { opacity: 0; } .ds-cosmic-emblem, .ds-island-content { transform: none !important; } }

.ds-island-pill { box-sizing: border-box; color: #f1edff; font-family: 'Segoe UI Variable', 'Segoe UI', sans-serif; user-select: none; } .ds-island-pill:focus-visible { outline: 2px solid var(--accent, #c6abff); outline-offset: 4px; }
.ds-island-shell { overflow: hidden; }

.ds-island-canvas { --surface: #0c0914; --accent: #c6abff; --muted: #b4aacb; font-family: 'Segoe UI Variable','Segoe UI',sans-serif; } .ds-island-canvas { --text:#f1edff; --control:#ffffff0c; --control-hover:#ffffff17; --line:#e8d4ff17; color:var(--text); font-size:13px; line-height:1.45; }
.ds-island-canvas[data-theme="light"] { --surface:#faf7ff; --text:#291c3c; --muted:#675a76; --accent:#7441be; --control:#49256e09; --control-hover:#49256e13; --line:#49256e1b; }
.ds-island-shell { color:var(--text); overflow:hidden; }
.ds-island-shell.ds-is-expanded { padding:15px 16px 10px; align-items:stretch; cursor:default; }
.ds-is-expanded>.ds-cosmic-sky { opacity:.32; height:58px; bottom:auto; }
.ds-is-expanded .ds-cosmic-stars { width:148px; height:36px; right:12px; left:auto; }
.ds-panel-content { position:relative; z-index:1; width:100%; height:100%; display:flex; flex-direction:column; gap:8px; min-width:0; }
.ds-panel-header { display:flex; align-items:center; gap:8px; height:28px; flex:none; }
.ds-panel-name { font-size:15px; font-weight:650; letter-spacing:-.03em; }
.ds-header-divider { width:1px; height:12px; background:var(--line); margin:0 2px; }
.ds-panel-title { color:var(--muted); font-size:12px; }
.ds-spacer { flex:1; }
.ds-island-shell button { color:inherit; font:inherit; border:0; background:var(--control); border-radius:9px; min-height:27px; display:inline-flex; align-items:center; justify-content:center; gap:6px; padding:5px 10px; cursor:pointer; transition:background .12s ease; }
.ds-island-shell button:hover { background:var(--control-hover); }
.ds-island-shell button:disabled { opacity:.4; cursor:default; }
.ds-island-shell button:focus-visible,.ds-island-shell input:focus-visible,.ds-island-shell textarea:focus-visible,.ds-island-shell select:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }
.ds-island-shell .ds-icon-button { min-height:27px; width:27px; padding:4px; border-radius:9px; background:transparent; flex:none; }
.ds-island-shell .ds-icon-button.ds-active { color:var(--accent); background:var(--control-hover); }
.ds-island-shell .ds-primary-button { background:var(--accent); color:#221332; font-weight:600; }
[data-theme="light"] .ds-primary-button { color:white; }
.ds-island-shell .ds-primary-button:hover { filter:brightness(1.06); }
.ds-island-shell .ds-text-button { background:transparent; padding:3px 0; color:var(--muted); min-height:23px; font-size:11px; }
.ds-island-shell .ds-compact-button { font-size:11px; padding:4px 8px; }
.ds-island-shell .ds-danger { color:#f6a8b6; }
[data-theme="light"] .ds-danger { color:#a62142; }
.ds-island-shell input:not([type="checkbox"]):not([type="range"]),.ds-island-shell textarea,.ds-island-shell select { min-width:0; color:var(--text); background:var(--control); border:1px solid var(--line); border-radius:9px; padding:7px 9px; font:inherit; font-size:12px; caret-color:var(--accent); outline-offset:1px; user-select:text; }
.ds-island-shell input::placeholder,.ds-island-shell textarea::placeholder { color:var(--muted); opacity:.85; }
.ds-island-shell select { cursor:pointer; padding-right:16px; }
.ds-island-shell option { background:#21182f; color:#f1edff; }
[data-theme="light"] option { background:#faf7ff; color:#291c3c; }
.ds-island-shell textarea { resize:none; }
.ds-island-shell input[type="checkbox"] { accent-color:var(--accent); width:16px; height:16px; cursor:pointer; flex:none; }
.ds-island-shell input[type="range"] { accent-color:var(--accent); height:4px; cursor:pointer; width:100%; }
.ds-tab-bar { display:flex; justify-content:space-between; padding:3px; background:var(--control); border-radius:13px; flex:none; }
.ds-tab-bar button { position:relative; background:transparent; width:calc(100% / 6); height:31px; color:var(--muted); }
.ds-tab-bar button[aria-pressed="true"] { color:var(--text); }
.ds-tab-bar button svg { position:relative; z-index:1; }
.ds-tab-highlight { position:absolute; inset:0; border-radius:10px; background:var(--control-hover); }
.ds-panel-body { flex:1; min-height:0; position:relative; overflow:hidden; }
.ds-feature { width:100%; height:100%; overflow:auto; padding:0 3px 1px 0; scrollbar-width:thin; scrollbar-color:#9c7dc144 transparent; }
.ds-feature::-webkit-scrollbar { width:5px; }
.ds-feature::-webkit-scrollbar-thumb { background:#9c7dc144; border-radius:9px; }
.ds-feature p { margin:5px 0; }
.ds-feature h2,.ds-feature h3,.ds-feature h4 { margin:0; font-weight:600; letter-spacing:-.025em; }
.ds-feature h2 { font-size:22px; }
.ds-feature h3 { font-size:13px; }
.ds-feature h4 { font-size:12px; }
.ds-feature small,.ds-muted { font-size:10px; color:var(--muted); }
.ds-toolbar { display:flex; align-items:center; gap:6px; min-height:28px; margin-bottom:8px; }
.ds-small-segment { display:flex; gap:2px; padding:2px; background:var(--control); border-radius:9px; }
.ds-small-segment button { min-height:23px; padding:2px 9px; font-size:11px; background:transparent; color:var(--muted); }
.ds-small-segment button[aria-pressed="true"] { color:var(--text); background:var(--control-hover); }
.ds-panel-footer { display:flex; align-items:center; border-top:1px solid var(--line); padding-top:7px; flex:none; }
.ds-quick-launch { display:flex; align-items:center; gap:5px; }
.ds-quick-launch button { font-size:10px; padding:5px 9px; gap:5px; color:var(--muted); background:transparent; }
.ds-quick-launch button:hover { color:var(--text); }
.ds-quick-launch button:first-child svg { color:#e6a7bc; }
.ds-quick-launch button:nth-child(2) svg { color:#a5c7ff; }
.ds-quick-launch button:nth-child(3) svg { color:#a5d6b0; }
[data-theme="light"] .ds-quick-launch svg { color:var(--accent)!important; }
.ds-empty-state { min-height:150px; height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; padding:10px 25px; }
.ds-empty-orbit { display:grid; place-items:center; width:47px; height:47px; border-radius:50%; color:var(--accent); background:radial-gradient(ellipse,#b482f82e,transparent 70%); margin-bottom:7px; }
.ds-empty-state h3 { font-size:14px; margin:0 0 4px; letter-spacing:-.02em; font-weight:600; }
.ds-empty-state p { font-size:11px; line-height:1.5; color:var(--muted); max-width:290px; margin:0; }
.ds-empty-state button { margin-top:10px; font-size:11px; }
.ds-loading-state { display:flex; align-items:center; justify-content:center; gap:9px; height:100%; color:var(--muted); }
.ds-spinner { flex:none; display:inline-block; width:14px; height:14px; border:1.5px solid var(--line); border-top-color:var(--accent); border-radius:50%; animation:orbit-turn .8s linear infinite; }
.ds-loading-copy { padding:12px; text-align:center; color:var(--muted); font-size:11px; }
.ds-toast { position:absolute; z-index:12; bottom:39px; left:6px; right:6px; display:flex; align-items:center; gap:7px; padding:8px 11px; border-radius:11px; background:#302340; color:#f1edff; font-size:11px; box-shadow:0 5px 18px #0005; overflow-wrap:anywhere; }
.ds-toast.ds-error { background:#452334; color:#ffe0e7; }
.ds-drop-overlay { position:absolute; z-index:10; inset:0; border:1px dashed var(--accent); border-radius:16px; display:flex; flex-direction:column; gap:7px; align-items:center; justify-content:center; background:var(--surface); color:var(--accent); pointer-events:none; animation:drop-breathe 1.2s ease-in-out infinite alternate; }
.ds-drop-overlay span { font-size:11px; color:var(--muted); }
@keyframes drop-breathe { to { opacity:.8; } }
.ds-permission-note,.ds-download-proposal { display:flex; align-items:center; gap:8px; padding:9px; border-radius:11px; background:var(--control); margin-bottom:8px; }
.ds-permission-note>svg,.ds-download-proposal>svg { color:var(--accent); flex:none; }
.ds-permission-note div,.ds-download-proposal>span { min-width:0; flex:1; }
.ds-permission-note strong,.ds-download-proposal strong { display:block; font-size:11px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.ds-permission-note p,.ds-download-proposal small { display:block; margin:0; font-size:10px; color:var(--muted); }
.ds-permission-note button,.ds-download-proposal button { font-size:10px; flex:none; }
.ds-inline-compose { display:flex; gap:6px; margin-bottom:8px; }
.ds-inline-compose input { flex:1; }
.ds-inline-compose button { font-size:11px; }
.ds-stack-row { display:flex; align-items:center; gap:5px; margin-bottom:7px; }
.ds-stack-row select { max-width:145px; font-size:10px; padding:4px 7px; height:26px; }
.ds-shelf-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:6px; }
.ds-shelf-tile { display:flex; align-items:center; min-width:0; min-height:57px; border-radius:12px; background:var(--control); }
.ds-shelf-tile:hover { background:var(--control-hover); }
.ds-shelf-tile.ds-missing { opacity:.65; }
.ds-shelf-tile .ds-tile-main { min-width:0; flex:1; background:transparent; text-align:left; padding:9px 4px 9px 9px; justify-content:flex-start; gap:8px; }
.ds-file-art { width:30px; height:33px; display:grid; place-items:center; flex:none; color:var(--accent); }
.ds-file-art img { width:30px; height:33px; object-fit:contain; border-radius:5px; }
.ds-file-label { min-width:0; display:flex; flex-direction:column; gap:2px; }
.ds-file-label strong { font-size:11px; font-weight:500; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.ds-file-label small { font-size:9px; }
.ds-tile-end { flex:none; display:flex; align-items:center; padding-right:3px; color:var(--muted); }
.ds-tile-end .ds-icon-button { width:20px; padding:2px; }
.ds-tile-end .ds-icon-button svg { width:14px; }
.ds-progress-ring { display:inline-grid; position:relative; place-items:center; flex:none; }
.ds-progress-ring>svg { width:100%; height:100%; transform:rotate(-90deg); }
.ds-progress-ring circle { fill:none; stroke-width:2.5; }
.ds-ring-track { stroke:var(--line); }
.ds-ring-value { stroke:var(--accent); stroke-linecap:round; }
.ds-ring-content { position:absolute; inset:0; display:grid; place-items:center; text-align:center; }
.ds-ring-content>span { display:flex; flex-direction:column; gap:2px; }
.ds-shelf-detail input { width:100%; }
.ds-detail-path { font-size:11px; color:var(--muted); user-select:text; overflow-wrap:anywhere; max-height:64px; overflow:auto; white-space:pre-wrap; }
.ds-action-row { display:flex; flex-wrap:wrap; gap:5px; margin:8px 0; }
.ds-action-row button { font-size:10px; }
.ds-action-row svg { width:14px; }
.ds-inline-field { display:flex; align-items:center; gap:7px; margin:7px 0; font-size:11px; }
.ds-inline-field label { color:var(--muted); }
.ds-inline-field select { flex:1; }
.ds-inline-field input { width:60px; }
.ds-cleanup-preview { padding:8px 10px; border-radius:11px; background:var(--control); font-size:11px; }
.ds-cleanup-preview p { white-space:pre-wrap; user-select:text; overflow-wrap:anywhere; }
.ds-cleanup-preview small { display:block; margin-top:5px; }
.ds-search-box { display:flex; align-items:center; gap:8px; background:var(--control); padding:3px 6px 3px 10px; border-radius:12px; margin-bottom:9px; }
.ds-search-box>svg { color:var(--muted); flex:none; }
.ds-search-box input { flex:1; border:0!important; background:transparent!important; padding:6px 0!important; }
.ds-definition-body { user-select:text; }
.ds-word-heading { display:flex; align-items:center; gap:5px; }
.ds-word-heading h2 { line-height:1.2; }
.ds-phonetic { font-size:12px; color:var(--accent); }
.ds-cache-label { display:block; margin:4px 0 10px; }
.ds-meaning { margin-bottom:12px; }
.ds-part-of-speech { display:inline-block; color:var(--accent); background:var(--control); border-radius:6px; font-size:10px; padding:2px 7px; margin-bottom:4px; font-style:italic; }
.ds-definition { margin:5px 0 8px; font-size:12px; }
.ds-definition blockquote { margin:4px 0; color:var(--muted); font-size:11px; font-style:italic; }
.ds-synonyms { display:flex; flex-wrap:wrap; gap:5px; margin-top:7px; }
.ds-synonyms button { font-size:10px; min-height:22px; padding:3px 8px; }
.ds-saved-words { padding:8px; }
.ds-focus-view { display:flex; flex-direction:column; justify-content:center; }
.ds-focus-clock { display:flex; align-items:center; gap:20px; }
.ds-focus-clock .ds-ring-content strong { font-size:29px; font-weight:500; font-variant-numeric:tabular-nums; letter-spacing:-.04em; }
.ds-focus-clock .ds-ring-content small { font-size:10px; }
.ds-focus-copy { flex:1; }
.ds-focus-copy h2 { font-size:18px; line-height:1.2; }
.ds-focus-copy p { font-size:11px; color:var(--muted); margin:8px 0; }
.ds-focus-cycles { display:flex; gap:4px; margin:10px 0 3px; }
.ds-focus-cycles span { width:6px; height:6px; border-radius:50%; background:var(--line); }
.ds-focus-cycles span.ds-done { background:var(--accent); }
.ds-timer-actions { display:flex; justify-content:center; gap:8px; margin-top:10px; }
.ds-timer-actions button { min-width:90px; font-size:11px; }
.ds-timer-settings-hint { font-size:10px; color:var(--muted); text-align:center; }
.ds-now-playing { display:flex; gap:17px; align-items:center; margin:5px 0 12px; }
.ds-album-art { flex:none; width:92px; height:92px; background:var(--control); color:var(--accent); border-radius:16px; display:grid; place-items:center; overflow:hidden; }
.ds-album-art img { width:100%; height:100%; object-fit:cover; }
.ds-track-info { min-width:0; flex:1; }
.ds-track-info>small { font-size:9px; letter-spacing:.08em; color:var(--accent); }
.ds-track-info h2 { font-size:19px; line-height:1.25; margin:5px 0; overflow-wrap:anywhere; }
.ds-track-info p { font-size:12px; color:var(--muted); }
.ds-waveform { display:flex; align-items:center; gap:3px; height:23px; color:var(--accent); }
.ds-waveform span { width:2px; border-radius:5px; background:currentColor; transform-origin:center; }
.ds-waveform.ds-playing span { animation:wave-pulse .8s ease-in-out infinite alternate; }
@keyframes wave-pulse { from { transform:scaleY(.35); } to { transform:scaleY(1); } }
.ds-seek>div { display:flex; justify-content:space-between; margin-top:3px; }
.ds-playback-controls { display:flex; justify-content:center; align-items:center; gap:22px; margin-top:5px; }
.ds-playback-controls .ds-play-button { width:43px; height:43px; border-radius:50%; background:var(--accent); color:#221332; }
.ds-idle-album { width:21px; height:21px; object-fit:cover; border-radius:50%; }
.ds-idle-wave { margin-left:auto; gap:2px; height:18px; }
.ds-idle-timer { font-size:13px; font-variant-numeric:tabular-nums; margin-right:auto; }
.ds-peek-copy { flex:1; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:11px; }
.ds-island-shell .ds-peek-action { font-size:10px; min-height:22px; padding:3px 8px; background:#c6abff27; color:var(--accent); }
.ds-notes-view { display:flex; flex-direction:column; }
.ds-notes-view select { max-width:210px; }
.ds-scratchpad { flex:1; width:100%; line-height:1.7; min-height:110px; background:transparent!important; border:0!important; padding:4px 3px!important; font-size:13px!important; }
.ds-usage-overview { display:flex; align-items:center; gap:18px; }
.ds-donut { flex:none; width:118px; height:118px; }
.ds-donut-track { fill:none; stroke:var(--line); stroke-width:9; }
.ds-donut-total { fill:var(--text); font-size:15px; font-weight:600; font-variant-numeric:tabular-nums; }
.ds-donut-caption { fill:var(--muted); font-size:9px; }
.ds-usage-legend { flex:1; min-width:0; }
.ds-usage-legend button,.ds-legend-other { display:flex; align-items:center; width:100%; gap:6px; padding:3px!important; min-height:21px!important; background:transparent!important; font-size:10px!important; text-align:left; }
.ds-usage-legend button span:not(.ds-app-color),.ds-legend-other>span:not(.ds-app-color) { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; flex:1; }
.ds-usage-legend button strong,.ds-legend-other strong { margin-left:auto; font-size:10px; font-weight:500; font-variant-numeric:tabular-nums; }
.ds-usage-legend img { width:14px; height:14px; object-fit:contain; }
.ds-app-color { width:7px; height:7px; border-radius:50%; flex:none; }
.ds-timeline-header { display:flex; justify-content:space-between; margin:10px 0 5px; font-size:10px; }
.ds-timeline { display:grid; gap:3px; height:65px; }
.ds-timeline-column { display:flex; flex-direction:column; justify-content:flex-end; min-width:0; }
.ds-timeline-bar { min-height:1px; border-radius:3px; overflow:hidden; display:flex; flex-direction:column-reverse; background:var(--line); }
.ds-timeline-bar span { display:block; min-height:1px; flex-shrink:0; }
.ds-timeline-column>small { height:14px; font-size:8px; text-align:center; margin-top:4px; }
.ds-app-total { font-size:22px; font-variant-numeric:tabular-nums; }
.ds-app-total small { font-size:10px; }
.ds-settings-view label:not(.ds-setting-toggle) { display:flex; flex-direction:column; gap:4px; font-size:10px; color:var(--muted); margin:8px 0; }
.ds-settings-view label input,.ds-settings-view label select { width:100%; }
